// Skip anyone we must not email, whatever their lifecycle says. A bounced
// address and an explicit opt-out both outrank a campaign.
//
// The from-address and the subject are also settled here, once, so that the
// send node and the record call cannot disagree about what actually went out.
// The SMTP response does not echo the subject back, so if it were only set on
// the send node the CRM would record null for every message.

const FROM = 'marc@serafines.de';

const out = [];

for (const item of $input.all()) {
  const c = item.json;

  if (!c.email) continue;
  if (c.bounced_at) continue;
  if (c.unsubscribed_at) continue;

  out.push({
    json: {
      ...c,
      _from: FROM,
      // No company reference here on purpose — see the Setup note. The
      // contacts endpoint returns company_id, not a company object, so
      // {{ $json.company.name }} renders empty for everyone.
      _subject: 'Quick question about your setup',
    },
  });
}

return out;

// Pair each send result back up with the contact it went to, and pull out the
// Message-ID. That id is the entire basis of thread-accurate reply matching:
// without it the CRM can still match a reply by from-address, but it cannot
// tell which campaign the reply answers, and it misses anyone who writes back
// from a different address.
//
// itemMatching() is what does the pairing. Indexing the source node by
// position instead — all()[i] — looks equivalent and usually is, right up
// until one send fails or the batch is reordered; then contacts and message
// ids cross silently and the CRM records a Message-ID against the wrong
// person. That is unrecoverable after the fact, because nothing downstream
// knows the pairing was ever wrong.

const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const sent = items[i].json;
  const contact = $('Drop bounced and opted-out').itemMatching(i).json;

  // nodemailer reports per-recipient outcomes. An accepted envelope that
  // rejected the only recipient is not a delivered email, and recording it
  // would leave the CRM waiting for a reply to a message nobody received.
  const rejected = Array.isArray(sent.rejected) ? sent.rejected : [];
  if (rejected.length > 0) {
    console.warn(
      `SMTP rejected ${rejected.join(', ')} for ${contact.email}. Not ` +
      `recording a send for this contact.`,
    );
    continue;
  }

  const messageId =
    sent.messageId || sent.message_id || sent.messageID || null;

  if (!messageId) {
    // Loud on purpose. Silently losing threading is the failure mode that is
    // hardest to notice later, because replies still half-work.
    console.warn(
      `No Message-ID returned for ${contact.email}. Reply matching for this ` +
      `message will fall back to the from-address.`,
    );
    continue;
  }

  out.push({
    json: {
      message_id: messageId,
      contact_email: contact.email,
      from_email: contact._from,
      subject: contact._subject,
      sent_at: new Date().toISOString(),
    },
  });
}

return out;

// The endpoint answers with contact_matched. A false there means the email
// went to somebody the CRM does not know, so any reply to this thread will
// land in the unmatched queue instead of on a person — the API's own comment
// calls this out as worth alerting on.
//
// This is why the POST above no longer sets neverError: with errors
// suppressed, a 400 for a missing message_id and a 500 from Supabase both
// looked like success, and this check never saw them either.

for (const item of $input.all()) {
  if (item.json.contact_matched === false) {
    console.warn(
      `Recorded ${item.json.message_id} but no contact matched ` +
      `${item.json.contact_email}. Replies will go to the unmatched queue.`,
    );
  }
}

return $input.all();
